class FlightDB(DB):
    """Database of all flights, users, and reservations."""

    flights: Dict[str, Flight] = Field(
        description="Dictionary of all flights indexed by flight number"
    )
    users: Dict[str, User] = Field(
        description="Dictionary of all users indexed by user ID"
    )
    reservations: Dict[str, Reservation] = Field(
        description="Dictionary of all reservations indexed by reservation ID"
    )

    def get_statistics(self) -> dict[str, Any]:
        """Get the statistics of the database."""
        num_flights = len(self.flights)
        num_flights_instances = sum(
            len(flight.dates) for flight in self.flights.values()
        )
        num_users = len(self.users)
        num_reservations = len(self.reservations)
        return {
            "num_flights": num_flights,
            "num_flights_instances": num_flights_instances,
            "num_users": num_users,
            "num_reservations": num_reservations,
        }

    @classmethod
    def load(cls, path: Optional[str] = None) -> "FlightDB":
        """Build the scoped tau2 airline tree from the unified world.db.

        `path` is accepted for back-compat (the old db.json seed) but ignored;
        data is read from world.db (see CUGA_WORLD_DB). Flights/reservations are
        scoped by `source_skill='tau2Airline'`; users by `skill_ids_json`.
        """
        conn = _connect()
        try:
            flights: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM flights WHERE source_skill=?", (SOURCE_SKILL,)
            ):
                flights[r["flight_id"]] = {
                    "flight_number": r["flight_id"],
                    "origin": r["origin"],
                    "destination": r["destination"],
                    "scheduled_departure_time_est": r["departure_time"],
                    "scheduled_arrival_time_est": r["arrival_time"],
                    "dates": json.loads(r["dates_json"] or "{}"),
                }

            # Reservation ids per user (User.reservations is derived, not stored).
            resv_by_user: Dict[str, list] = {}
            reservations: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM flight_bookings WHERE source_skill=?", (SOURCE_SKILL,)
            ):
                res_flights = []
                for fj in json.loads(r["flights_json"] or "[]"):
                    res_flights.append(
                        {
                            "flight_number": fj.get("flight_number") or fj.get("flight_id"),
                            "origin": fj.get("origin", ""),
                            "destination": fj.get("destination", ""),
                            "date": fj.get("date", ""),
                            "price": fj.get("price", 0),
                        }
                    )
                reservations[r["booking_id"]] = {
                    "reservation_id": r["booking_id"],
                    "user_id": r["user_id"],
                    "origin": r["origin"],
                    "destination": r["destination"],
                    "flight_type": r["flight_type"] if r["flight_type"] in _TAU2_FLIGHT_TYPES else "one_way",
                    "cabin": r["cabin_class"] if r["cabin_class"] in _TAU2_CABINS else "economy",
                    "flights": res_flights,
                    "passengers": json.loads(r["passengers_json"] or "[]"),
                    "payment_history": json.loads(r["payment_history_json"] or "[]"),
                    "created_at": r["booked_at"],
                    "total_baggages": r["total_baggages"],
                    "nonfree_baggages": r["nonfree_baggages"],
                    "insurance": r["add_insurance"] if r["add_insurance"] in ("yes", "no") else "no",
                    "status": "cancelled" if r["status"] == "cancelled" else None,
                }
                resv_by_user.setdefault(r["user_id"], []).append(r["booking_id"])

            users: Dict[str, Any] = {}
            for r in conn.execute(
                "SELECT * FROM users WHERE skill_ids_json LIKE ?",
                (f'%"{SOURCE_SKILL}"%',),
            ):
                users[r["user_id"]] = {
                    "user_id": r["user_id"],
                    "name": _split_name(r["name"]),
                    "address": json.loads(r["address_json"] or "{}"),
                    "email": r["email"],
                    "dob": r["dob"] or "",
                    "payment_methods": json.loads(r["payment_methods_json"] or "{}"),
                    "saved_passengers": json.loads(r["saved_passengers_json"] or "[]"),
                    "membership": _TIER_TO_MEMBERSHIP.get(r["loyalty_tier"], r["loyalty_tier"]),
                    "reservations": resv_by_user.get(r["user_id"], []),
                }
        finally:

from enum import Enum
from typing import Annotated, Any, Callable, Dict, Optional, TypeVar

from pydantic import BaseModel, Field

from tau2.environment.db import DB
from tau2.environment.tool import Tool, as_tool
from tau2.utils import get_dict_hash, update_pydantic_model_with_dict

TOOL_ATTR = "__tool__"
TOOL_TYPE_ATTR = "__tool_type__"


T = TypeVar("T", bound=DB)


class ToolKitType(type):
    """Metaclass for ToolKit classes."""

    def __init__(cls, name, bases, attrs):
        func_tools = {}
        for name, method in attrs.items():
            if isinstance(method, property):
                method = method.fget
            if hasattr(method, TOOL_ATTR):
                func_tools[name] = method

        @property
        def _func_tools(self) -> Dict[str, Callable]:
            """Get the tools available in the ToolKit."""
            all_func_tools = func_tools.copy()
            try:
                all_func_tools.update(super(cls, self)._func_tools)
            except AttributeError:
                pass
            return all_func_tools

        cls._func_tools = _func_tools


class ToolType(str, Enum):
    """Type of a tool."""

    READ = "read"
    WRITE = "write"
    THINK = "think"
    GENERIC = "generic"


def is_tool(tool_type: ToolType = ToolType.READ):

def is_tool(tool_type: ToolType = ToolType.READ):
    """Decorator to mark a function as a tool.

    Args:
        write: Whether this tool modifies state (True) or just reads state (False)
    """

    def decorator(func):
        setattr(func, TOOL_ATTR, True)
        setattr(func, TOOL_TYPE_ATTR, tool_type)
        return func

    return decorator


class ToolKitBase(metaclass=ToolKitType):
    """Base class for ToolKit classes."""

    def __init__(self, db: Optional[T] = None):
        self.db: Optional[T] = db

    @property
    def tools(self) -> Dict[str, Callable]:
        """Get the tools available in the ToolKit."""
        return {name: getattr(self, name) for name in self._func_tools.keys()}

    def use_tool(self, tool_name: str, **kwargs) -> str:
        """Use a tool."""
        if tool_name not in self.tools:
            raise ValueError(f"Tool '{tool_name}' not found.")
        return self.tools[tool_name](**kwargs)

    def get_tools(self) -> Dict[str, Tool]:
        """Get the tools available in the ToolKit.
        Uses the `as_tool` to convert the functions to Tool objects.

        Returns:
            A dictionary of tools available in the ToolKit.
        """
        # NOTE: as_tool needs to get the function (self.foo), not the `foo(self, ...)`
        # Otherwise, the `self` will exists in the arguments.
        # Therefore, it needs to be called with getattr(self, name)
        return {name: as_tool(tool) for name, tool in self.tools.items()}

    def has_tool(self, tool_name: str) -> bool:
        """Check if a tool exists in the ToolKit."""
        return tool_name in self.tools

    def tool_type(self, tool_name: str) -> ToolType:
        """Get the type of a tool."""
        return getattr(self.tools[tool_name], TOOL_TYPE_ATTR)

    def get_statistics(self) -> dict[str, Any]:
        """Get the statistics of the ToolKit."""
        num_tools = len(self.tools)
        num_read_tools = sum(
            self.tool_type(name) == ToolType.READ for name in self.tools
        )
        num_write_tools = sum(
            self.tool_type(name) == ToolType.WRITE for name in self.tools
        )
        num_think_tools = sum(
            self.tool_type(name) == ToolType.THINK for name in self.tools
        )
        num_generic_tools = sum(
            self.tool_type(name) == ToolType.GENERIC for name in self.tools
        )
        return {
            "num_tools": num_tools,
            "num_read_tools": num_read_tools,
            "num_write_tools": num_write_tools,
            "num_think_tools": num_think_tools,
            "num_generic_tools": num_generic_tools,
        }

    def update_db(self, update_data: Optional[dict[str, Any]] = None):
        """Update the database of the ToolKit."""
        if update_data is None:
            update_data = {}
        if self.db is None:
            raise ValueError("Database has not been initialized.")
        self.db = update_pydantic_model_with_dict(self.db, update_data)

    def get_db_hash(self) -> str:
        """Get the hash of the database."""
        return get_dict_hash(self.db.model_dump())


